-- Forfeit winners for ultirzr-loaded USAU games (2014-2026).
-- ultirzr reports forfeits as "W"/"F" in HomeTeamScore/AwayTeamScore; ingest-from-ultirzr
-- dropped the letters (null scores, no winner) until 2026-09-28. Pairs below were read from
-- ultirzr /events/{id} for all 562 affected events. Home = team_a in that pipeline (spot-checked 80/80).
-- Only fills a null winner on an unscored final ultirzr game; HTML-scraped rows are untouched.
-- Undo: update usau_games set winner_team_id = null where usau_event_game_id in (<ids below>).
set local statement_timeout = '120s';
set local lock_timeout = '5s';

update public.usau_games g
set winner_team_id = case v.side when 'home' then g.team_a_id else g.team_b_id end
